// Factory Analytics over a real mach-observer (built from this working tree with `go build`), on
// projects generated by `mach-synth --analytics` into the scratch folder: empty, one run, tiny, medium.
// Mode `live`. The API checks run whenever the observer serves the route; the browser checks run once
// the Shell mounts a live Analytics provider, and SKIP with the reason until then.
/* global document, location, innerHeight */
import { after, before, describe, test } from "node:test";
import assert from "node:assert/strict";
import {
  AREAS,
  WINDOW_GROUP,
  SEL,
  analyticsReady,
  analyticsRequests,
  analyticsRoutes,
  apiGet,
  apiSession,
  consoleErrors,
  DEV_ORIGIN,
  ensureStack,
  gotoArea,
  hashParams,
  launch,
  log,
  makeProject,
  MODE,
  openShell,
  proseInUrls,
  readReadouts,
  requestOffenders,
  sideways,
  skip,
  sleep,
  startObserver,
  stopOwn,
  unavailableOffenders,
  waitCaughtUp,
  workspaceState,
} from "./analytics-lib.mjs";

const run = MODE === "all" || MODE === "live";
const PORTS = { medium: 4432, tiny: 4433, one: 4436, empty: 4437 };
const KINDS = ["empty", "one", "tiny", "medium"];
let browser;
const obs = {};
const cookie = {};
const routes = {};
const summaries = {};
const pages = [];
let liveUi = null; // null: not looked yet; string: why it is not there; true: mounted

before(async () => {
  if (!run) return;
  await ensureStack({ tools: true });
  for (const k of KINDS) {
    const { dir, summary } = makeProject(k);
    summaries[k] = summary;
    obs[k] = await startObserver(dir, PORTS[k]);
    cookie[k] = await apiSession(obs[k]);
    await waitCaughtUp(obs[k], cookie[k]);
    routes[k] = await analyticsRoutes(obs[k], cookie[k]);
    log(k, "routes", JSON.stringify(routes[k]));
  }
  browser = await launch();
});

after(async () => {
  await browser?.close();
  for (const o of Object.values(obs)) await o.stop();
  stopOwn();
});

async function open(kind, hash = "#analytics", opts) {
  const o = await openShell(browser, obs[kind], hash, opts);
  pages.push(o.page);
  return o;
}

/** A GET with this suite's own session on `kind`'s observer; a new session when the old one is refused (401). */
async function api(kind, path) {
  let g = await apiGet(obs[kind], cookie[kind], path);
  if (g.status === 401) {
    cookie[kind] = await apiSession(obs[kind]);
    g = await apiGet(obs[kind], cookie[kind], path);
  }
  return g;
}

/** Is a live Analytics provider mounted in the Shell? true, or the reason it is not. */
async function live() {
  if (liveUi !== null) return liveUi;
  let opened;
  try {
    opened = await open("medium", "#analytics");
  } catch (error) {
    liveUi = `the Analytics workspace did not appear over a live observer: ${String(error?.message ?? error).split("\n")[0]}`;
    return liveUi;
  }
  const { page, context } = opened;
  const s = await workspaceState(page);
  if (s.notConnected) liveUi = `the Shell mounts the placeholder for a live source ("${s.text.slice(0, 120)}"): the live provider is not wired yet (shell, client)`;
  else if (s.simulatedChip) liveUi = "the workspace over a live observer is labelled Simulated: a fixture is shown beside a real source";
  else if (!s.sheet) liveUi = `no Analytics sheet over a live observer: ${s.text.slice(0, 160)}`;
  else liveUi = true;
  await context.close();
  return liveUi;
}
const needLive = async (t) => {
  const l = await live();
  if (l !== true) skip(t, l);
  return l === true;
};

/** The metric values a page's own metrics request returned, by id (the request replayed with the test's own session). */
async function apiValuesFor(kind, page, since = 0) {
  const req = analyticsRequests(page, since).filter((r) => r.route === "metrics");
  const out = {};
  for (const r of req) {
    const u = new URL(r.url);
    const g = await api(kind, `${u.pathname}${u.search}`);
    for (const m of g.data?.metrics ?? []) out[m.id] = m;
  }
  return out;
}

/** Every finite number in a metric row except counts of coverage and the window (value, numerator, denominator, sums, percentiles). */
function numbersIn(m) {
  const out = [];
  const walk = (x, key) => {
    if (typeof x === "number" && Number.isFinite(x) && !/_ms$|^(from|to|le)_?ms|eligible|counted|cursor/.test(key ?? "")) out.push(x);
    else if (Array.isArray(x)) x.forEach((y) => walk(y, key));
    else if (x && typeof x === "object") for (const [k, v] of Object.entries(x)) if (!["coverage", "window", "buckets", "groups"].includes(k)) walk(v, k);
  };
  walk(m, "");
  return out;
}

describe("Analytics over a real observer", { skip: run ? false : `E2E_AN_MODE=${MODE}` }, () => {
  // ------------------------------------------------------------ the API (works without the UI)

  test("every analytics route answers on every project, with the common envelope", async (t) => {
    const problems = [];
    const missing = [];
    for (const k of KINDS) {
      for (const [route, status] of Object.entries(routes[k])) {
        if (status !== "ok") {
          missing.push(`${route} (${status})`);
          continue;
        }
        const q = route === "contributors" ? "?metric=C1" : route === "metrics" ? "?ids=T1,Q2,C1,K1" : "";
        const g = await api(k, `/api/v1/analytics/${route}${q}`);
        for (const f of ["cursor", "generated_ms", "filters", "history"]) if (!(f in (g.data ?? {}))) problems.push(`${k} ${route}: no ${f}`);
      }
    }
    assert.deepEqual(problems, []);
    if (missing.length) skip(t, `routes not served yet: ${[...new Set(missing)].join(", ")}`);
  });

  test("missing is not zero: on the empty project every rate has no value and says why", async () => {
    const g = await api("empty", "/api/v1/analytics/metrics");
    assert.equal(g.status, 200);
    const bad = [];
    for (const m of g.data.metrics) {
      const rate = m.kind === "rate" || m.unit === "ratio" || m.unit === "%" || /rate|share/i.test(m.name);
      if (rate && m.value !== null && m.value !== undefined) bad.push(`${m.id} ${m.name} = ${m.value}`);
      if ((m.value === null || m.value === undefined) && !(m.null_reason || m.status_reason || m.availability_reason || m.reason)) bad.push(`${m.id}: no value and no reason`);
    }
    assert.deepEqual(bad, []);
  });

  test("the same cursor gives the same answer; an unknown parameter is refused", async () => {
    const a = await api("medium", "/api/v1/analytics/metrics?ids=T1,C1");
    const b = await api("medium", `/api/v1/analytics/metrics?ids=T1,C1&at=${encodeURIComponent(a.data.cursor)}`);
    assert.equal(b.status, 200);
    assert.deepEqual(
      b.data.metrics.map((m) => [m.id, m.value, m.sample_count]),
      a.data.metrics.map((m) => [m.id, m.value, m.sample_count]),
    );
    const bad = await api("medium", "/api/v1/analytics/metrics?ids=T1&colour=red");
    assert.equal(bad.status, 400, "an unknown parameter is not a 400");
  });

  // ------------------------------------------------------------ the workspace

  test("every area renders over each project with the source said, never Simulated", async (t) => {
    if (!(await needLive(t))) return;
    const problems = [];
    for (const k of KINDS) {
      for (const a of AREAS) {
        const { page, context } = await open(k, `#analytics?area=${a.id}`);
        const s = await workspaceState(page);
        if (s.sheet !== a.label) problems.push(`${k} ${a.id}: the sheet is ${s.sheet}`);
        if (s.simulatedChip) problems.push(`${k} ${a.id}: labelled Simulated over a real observer`);
        if (!["live", "replay"].includes(s.source)) problems.push(`${k} ${a.id}: data-analytics-source=${s.source}`);
        if (!/\bLive\b|Historical replay|recorded history/i.test(s.header)) problems.push(`${k} ${a.id}: the workspace bar does not say the source: ${s.header.slice(0, 120)}`);
        for (const o of await unavailableOffenders(page)) problems.push(`${k} ${a.id}: ${o.where}: ${o.why}`);
        await context.close();
      }
    }
    assert.deepEqual(problems, []);
  });

  test("every number shown is the observer's: no value where the API has none", async (t) => {
    if (!(await needLive(t))) return;
    const problems = [];
    let compared = 0;
    for (const k of ["empty", "one", "medium"]) {
      for (const a of AREAS) {
        const { page, context } = await open(k, `#analytics?area=${a.id}`);
        const rowsById = await apiValuesFor(k, page);
        for (const r of await readReadouts(page)) {
          const m = rowsById[r.id];
          if (!m) continue;
          compared++;
          const shown = r.value === null ? null : Number(r.value);
          // A readout may show the metric's value, its numerator, a total or a percentile: whichever it
          // shows must be a number the observer returned for that metric (no derived or invented figure).
          const served = numbersIn(m);
          if (!served.length && (shown !== null || /\d/.test(r.shown ?? ""))) problems.push(`${k} ${a.id} ${r.id}: the API has no number for it, the page shows ${r.shown ?? r.value}`);
          if (shown !== null && served.length && !served.some((x) => Math.abs(shown - x) <= 1e-6 * Math.max(1, Math.abs(x)))) problems.push(`${k} ${a.id} ${r.id}: shown ${shown}, not among the API's numbers for it (value ${m.value}, numerator ${m.numerator})`);
        }
        await context.close();
      }
    }
    assert.ok(compared > 0, "no readout could be matched to a metrics request (data-readout ids vs the requests' ids)");
    assert.deepEqual(problems, []);
  });

  test("a window preset changes every chart of the area together, at one cursor", async (t) => {
    if (!(await needLive(t))) return;
    const problems = [];
    for (const a of AREAS) {
      const { page, context } = await open("medium", `#analytics?area=${a.id}&win=all`);
      const t0 = Date.now();
      await page.getByRole("radiogroup", { name: WINDOW_GROUP }).getByRole("radio", { name: "7 days" }).click();
      await analyticsReady(page);
      await sleep(500);
      const reqs = analyticsRequests(page, t0);
      if (!reqs.length) {
        problems.push(`${a.id}: no analytics request after choosing 7 days`);
        await context.close();
        continue;
      }
      const ats = new Set(reqs.map((r) => r.params.at ?? "(none)"));
      const wins = new Set(reqs.map((r) => `${r.params.from_ms ?? ""}-${r.params.to_ms ?? ""}`));
      if (ats.size !== 1 || ats.has("(none)")) problems.push(`${a.id}: the area's requests used ${ats.size} cursors (${[...ats].join(", ")})${ats.has("(none)") ? `; without one: ${reqs.filter((r) => !r.params.at).map((r) => r.url.replace(/^.*\/analytics\//, "")).slice(0, 3).join(", ")}` : ""}`);
      // Several windows are allowed (a trend asks for earlier periods beside the chosen one); one cursor is not negotiable.
      if (wins.size !== 1) log(`${a.id}: ${wins.size} windows after 7 days: ${[...wins].join(", ")}`);
      const s = await workspaceState(page);
      if (s.cursor && !ats.has(s.cursor)) problems.push(`${a.id}: data-analytics-cursor ${s.cursor} is not the requests' cursor`);
      if (hashParams(s.hash).win !== "7d") problems.push(`${a.id}: the address has win=${hashParams(s.hash).win}`);
      await context.close();
    }
    assert.deepEqual(problems, []);
  });

  test("a brushed range re-queries the area with one window and one cursor", async (t) => {
    if (!(await needLive(t))) return;
    const { page, context } = await open("medium", "#analytics?area=pulse&win=all");
    const brush = page.locator(SEL.brush).first();
    if (!(await brush.count())) {
      await context.close();
      return skip(t, "no brush ([data-analytics-brush]) in the live workspace yet (areas)");
    }
    const t0 = Date.now();
    const box = await brush.boundingBox();
    await page.mouse.move(box.x + box.width * 0.25, box.y + box.height / 2);
    await page.mouse.down();
    await page.mouse.move(box.x + box.width * 0.6, box.y + box.height / 2, { steps: 8 });
    await page.mouse.up();
    await analyticsReady(page);
    await sleep(600);
    const reqs = analyticsRequests(page, t0);
    assert.ok(reqs.length > 0, "no request after the brush moved");
    const last = reqs.filter((r) => r.params.from_ms);
    assert.ok(last.length > 0, "no request carries the brushed window");
    const finalWin = `${last.at(-1).params.from_ms}-${last.at(-1).params.to_ms}`;
    const finalSet = reqs.filter((r) => `${r.params.from_ms}-${r.params.to_ms}` === finalWin);
    assert.equal(new Set(finalSet.map((r) => r.params.at)).size, 1, "the brushed window was read at several cursors");
    assert.match(hashParams((await workspaceState(page)).hash).win ?? "", /^\d+-\d+$/, "the address does not carry the brushed range");
    await context.close();
  });

  test("filters reach every request; cross-filter chips clear them", async (t) => {
    if (!(await needLive(t))) return;
    const { page, context } = await open("medium", "#analytics?area=quality&win=all");
    const t0 = Date.now();
    await page.getByRole("combobox", { name: "Risk" }).selectOption("high");
    await analyticsReady(page);
    await sleep(500);
    const reqs = analyticsRequests(page, t0);
    assert.ok(reqs.length > 0, "no request after the filter");
    assert.deepEqual(
      reqs.filter((r) => r.params.risk?.toLowerCase() !== "high").map((r) => r.url),
      [],
      "requests without the filter",
    );
    await context.close();
    // A cross-filter pick shows as a chip that clears it.
    const picked = await open("medium", "#analytics?area=quality&pick=target_kind:scenario");
    const chips = picked.page.locator(SEL.chip);
    if (!(await chips.count())) {
      await picked.context.close();
      return skip(t, "no chip (button[data-analytics-chip]) for pick=target_kind:scenario on Quality; the filter reached every request");
    }
    await chips.first().click();
    await analyticsReady(picked.page);
    assert.equal(hashParams((await workspaceState(picked.page)).hash).pick, undefined, "the chip did not clear the pick");
    await picked.context.close();
  });

  test("Rows → the entity in the Timeline (selected, in the window), on the floor, and Back to Analytics", async (t) => {
    if (!(await needLive(t))) return;
    // The first area, and the first Rows in it, whose drawer lists entities (Flow's C3 and C4 have no
    // contributor list in this observer; those are named in the log).
    let page;
    let context;
    let area;
    const drawer = (p) => p.locator(SEL.rowsDrawer);
    const empty = [];
    let found = false;
    for (area of ["flow", "quality", "reliability", "economics", "pulse"]) {
      ({ page, context } = await open("medium", `#analytics?area=${area}&win=all&risk=medium`));
      const rows = page.getByRole("button", { name: /^Rows$/ });
      await rows.first().waitFor({ timeout: 15000 }).catch(() => {});
      for (let i = 0; i < Math.min(await rows.count(), 8) && !found; i++) {
        await rows.nth(i).click();
        await drawer(page).waitFor({ timeout: 10000 });
        found = await drawer(page).locator("a[data-ref]").first().waitFor({ timeout: 6000 }).then(() => true, () => false);
        if (!found) {
          empty.push(`${area} ${await drawer(page).getAttribute("data-analytics-rows")}: ${(await drawer(page).innerText()).replace(/\s+/g, " ").slice(0, 70)}`);
          await page.keyboard.press("Escape");
          await sleep(200);
        }
      }
      if (found) break;
      await context.close();
    }
    if (empty.length) log("Rows that listed no entity:", empty.join(" | "));
    assert.ok(found, `no Rows in any area listed an entity: ${empty.join(" | ")}`);
    const link = drawer(page).locator("a[data-ref]").first();
    const ref = await link.getAttribute("data-ref");
    // The entity's interval, from the observer (contributors carry from_ms/to_ms/at_ms).
    const contrib = analyticsRequests(page).filter((r) => r.route === "contributors").at(-1);
    let span = null;
    if (contrib) {
      const u = new URL(contrib.url);
      const g = await api("medium", `${u.pathname}${u.search}`);
      const item = (g.data?.items ?? []).find((i) => i.ref === ref);
      if (item) span = { from: item.from_ms ?? item.at_ms, to: item.to_ms ?? item.at_ms };
    }
    await link.click();
    await page.waitForFunction(() => location.hash.startsWith("#timeline"), undefined, { timeout: 10000 });
    await page.waitForSelector("[data-timeline-workspace][data-timeline-ready]", { timeout: 30000 });
    const h = hashParams(await page.evaluate(() => location.hash));
    assert.equal(h.sel, ref, "the Timeline does not carry the entity");
    const win = await page.evaluate(() => document.querySelector("[data-timeline-window]")?.getAttribute("data-timeline-window"));
    if (span?.from != null) {
      const [from, to] = (win ?? "").split("-").map(Number);
      assert.ok(from <= span.from && to >= (span.to ?? span.from), `the Timeline's window ${win} does not hold the entity's interval ${span.from}-${span.to}`);
    }
    const inspector = await page.evaluate(() => document.querySelector("[data-inspector]")?.innerText ?? "");
    assert.ok(inspector.trim().length > 0, "the inspector is empty: the entity is not selected");
    await page.evaluate(() => document.activeElement?.blur());
    await page.keyboard.press("1");
    await sleep(600);
    const floor = hashParams(await page.evaluate(() => location.hash));
    assert.equal(floor.sel, ref, "the floor lost the selection");
    for (let i = 0; i < 4 && !(await page.evaluate(() => location.hash.startsWith("#analytics"))); i++) {
      await page.goBack();
      await sleep(500);
    }
    await analyticsReady(page);
    const back = hashParams(await page.evaluate(() => location.hash));
    assert.deepEqual({ area: back.area ?? "pulse", risk: back.risk }, { area, risk: "medium" }, "Back did not restore Analytics");
    await context.close();
  });

  test("a visit opened from Analytics on a fresh page lands with its row inside the tracks' viewport (10 runs)", async (t) => {
    if (!(await needLive(t))) return;
    // Each run a fresh browser context: the Timeline mounts for the first time and adds rows above the
    // revealed one while it settles; the row must still end up inside the tracks' viewport.
    const results = [];
    for (let run = 0; run < 10; run++) {
      const i = run % 3;
      const { page, context } = await open("medium", "#analytics?area=flow&station=build");
      const links = page.locator("main.an-sheet a[data-ref^='visit:']");
      await links.nth(i).waitFor({ timeout: 15000 }).catch(() => {});
      if ((await links.count()) <= i) {
        results.push({ run, i, ok: false, why: `only ${await links.count()} visit links on Flow at build` });
        await context.close();
        continue;
      }
      const link = links.nth(i);
      const ticket = /[A-Z]+-\d{3,}/.exec(`${await link.innerText()} ${(await link.getAttribute("title")) ?? ""}`)?.[0];
      const ref = await link.getAttribute("data-ref");
      await link.click();
      const seen = await page
        .waitForFunction(
          (ticket) => {
            const ws = document.querySelector("[data-workspace=timeline]");
            if (!ws) return false;
            for (const el of ws.querySelectorAll("*")) {
              if (el.children.length || el.textContent.trim() !== ticket) continue;
              const r = el.getBoundingClientRect();
              if (r.width > 0 && r.top > 250 && r.bottom < innerHeight) return { top: Math.round(r.top), bottom: Math.round(r.bottom) };
            }
            return false;
          },
          ticket,
          { timeout: 10000, polling: 100 },
        )
        .then((h) => h.jsonValue(), () => null);
      let where = null;
      if (!seen)
        where = await page.evaluate((ticket) => {
          const ws = document.querySelector("[data-workspace=timeline]");
          const hits = [...(ws?.querySelectorAll("*") ?? [])].filter((el) => !el.children.length && el.textContent.trim() === ticket).map((el) => Math.round(el.getBoundingClientRect().top));
          return { hash: location.hash, labelTops: hits, innerHeight };
        }, ticket);
      results.push({ run, i, ticket, ref, ok: Boolean(seen), at: seen, where });
      await context.close();
    }
    log("fresh-page reveal:", results.map((r) => `${r.run}:${r.ticket ?? "?"}:${r.ok ? `ok@${r.at.top}` : "MISS"}`).join(" "));
    const missed = results.filter((r) => !r.ok);
    assert.deepEqual(
      missed.map((r) => `run ${r.run} (link ${r.i}, ${r.ticket ?? "?"} ${r.ref ?? ""}): ${r.why ?? `label not inside the tracks' viewport within 10 s: ${JSON.stringify(r.where)}`}`),
      [],
      `${10 - missed.length} of 10 landed in view`,
    );
  });

  test("deep links round-trip for each area", async (t) => {
    if (!(await needLive(t))) return;
    const problems = [];
    for (const a of AREAS) {
      const hash = `#analytics?${new URLSearchParams({ area: a.id, win: "14d", risk: "medium", app: "web" })}`;
      const { page, context } = await open("medium", hash);
      const s = await workspaceState(page);
      if (s.sheet !== a.label) problems.push(`${a.id}: opened on ${s.sheet}`);
      const again = await openShell(browser, obs.medium, s.hash);
      const s2 = await workspaceState(again.page);
      // The same view: area, address, window and every readout's number (the bar's "generated at" clock may differ).
      await analyticsReady(page);
      await analyticsReady(again.page);
      // Numbers to 9 significant digits: a sum folded in another order differs in its last bits (reported, not failed).
      const norm = (r) => `${r.id}=${r.value === null ? null : Number(Number(r.value).toPrecision(9))}`;
      const v1 = (await readReadouts(page)).map(norm);
      const v2 = (await readReadouts(again.page)).map(norm);
      const r1 = JSON.stringify(v1);
      const r2 = JSON.stringify(v2);
      if (s2.sheet !== s.sheet) problems.push(`${a.id}: reopening shows ${s2.sheet}`);
      if (s2.hash !== s.hash) problems.push(`${a.id}: reopening ${s.hash} writes ${s2.hash}`);
      if (s2.window !== s.window) problems.push(`${a.id}: reopening changes the window ${s.window} -> ${s2.window}`);
      if (r1 !== r2) problems.push(`${a.id}: reopening shows other numbers: ${v1.filter((x) => !v2.includes(x)).slice(0, 4).join(", ")} became ${v2.filter((x) => !v1.includes(x)).slice(0, 4).join(", ")}`);
      await again.context.close();
      await context.close();
    }
    assert.deepEqual(problems, []);
  });

  test("keys 1-4 from and back to Analytics over a live source", async (t) => {
    if (!(await needLive(t))) return;
    const { page, context } = await open("medium", "#analytics?area=economics&win=7d");
    for (const k of ["1", "2", "3", "4"]) {
      await page.evaluate(() => document.activeElement?.blur());
      await page.keyboard.press(k);
      await sleep(500);
    }
    await analyticsReady(page);
    const s = await workspaceState(page);
    assert.equal(s.sheet, "Agent and model economics");
    assert.equal(hashParams(s.hash).win, "7d");
    await context.close();
  });

  test("through the playhead: no outcome later than the playhead", async (t) => {
    if (!(await needLive(t))) return;
    const sm = summaries.medium;
    if (!sm?.start_ms || !sm?.end_ms) return skip(t, "the medium project's summary has no start_ms/end_ms");
    // A time in the middle of the history, in ms (the address's `at` takes ms or an event id).
    const at = String(Math.floor((sm.start_ms + (sm.end_ms - sm.start_ms) / 2) / 1000) * 1000);
    const { page, context } = await open("medium", `#analytics?area=pulse&at=${encodeURIComponent(at)}`);
    // The whole workspace's text (workspaceState keeps only its first 2,000 characters).
    const held = await page
      // "Through the playhead at …", or since round 4 "Through <midnight>, the last whole UTC day before the playhead at …".
      .waitForFunction(() => /Through the playhead|before the playhead/i.test(document.querySelector("[data-analytics-workspace]")?.textContent ?? ""), undefined, { timeout: 15000 })
      .then(() => true, () => false);
    if (!held) {
      await context.close();
      return skip(t, `#analytics?area=pulse&at=${at} did not hold the playhead (no caption naming the playhead in the workspace) [shell, wire]`);
    }
    // The playhead bounds every query: `as_of_ms` (the observer's "nothing recorded later") or `to_ms`.
    const bound = (r) => Number(r.params.as_of_ms ?? r.params.to_ms ?? NaN);
    const all = analyticsRequests(page);
    const bounded = all.filter((r) => Number.isFinite(bound(r)));
    assert.ok(bounded.length > 0, `no analytics request is bounded by the playhead (as_of_ms or to_ms): ${JSON.stringify(all.map((r) => [r.route, r.params]).slice(-6))}`);
    const toMs = Math.max(...bounded.map(bound));
    assert.ok(toMs <= Number(at) + 1000, `a query is bounded at ${toMs}, after the playhead ${at}`);
    const lastLoad = all.slice(all.indexOf(bounded[0]));
    const unbounded = lastLoad.filter((r) => !Number.isFinite(bound(r)));
    assert.deepEqual(unbounded.map((r) => r.url), [], "queries made while the playhead is held without a bound");
    const param = bounded.some((r) => r.params.as_of_ms) ? "as_of_ms" : "to_ms";
    const through = await api("medium", `/api/v1/analytics/metrics?ids=T1,T2&${param}=${toMs}`);
    const headApi = await api("medium", "/api/v1/analytics/metrics?ids=T1,T2");
    const shown = Object.fromEntries((await readReadouts(page)).map((r) => [r.id, r.value === null ? null : Number(r.value)]));
    for (const m of through.data.metrics) {
      if (shown[m.id] === undefined) continue;
      assert.ok(shown[m.id] === null || numbersIn(m).includes(shown[m.id]), `${m.id} through the playhead: shown ${shown[m.id]}, the API at ${param}=${toMs} has ${m.value}`);
      const later = headApi.data.metrics.find((x) => x.id === m.id)?.value;
      if (later !== m.value) log(`${m.id}: ${m.value} through the playhead, ${later} at the head (the page shows the former)`);
    }
    await context.close();
  });

  test("nothing scrolls sideways at 1512x982, 1280x800 and 1100x700", async (t) => {
    if (!(await needLive(t))) return;
    const problems = [];
    for (const [width, height] of [
      [1512, 982],
      [1280, 800],
      [1100, 700],
    ]) {
      const { page, context } = await open("medium", "#analytics?area=pulse", { width, height });
      for (const a of AREAS) {
        await gotoArea(page, a.id);
        for (const s of await sideways(page)) problems.push(`${width}x${height} ${a.id}: ${s}`);
      }
      await context.close();
    }
    assert.deepEqual(problems, []);
  });

  test("every request is a GET to 127.0.0.1, no prose in any address, no console error", () => {
    const offenders = pages.flatMap((p) => requestOffenders(p).map((r) => `${r.method} ${r.url}`));
    const prose = proseInUrls([...new Set(pages.flatMap((p) => [...p.urls, ...p.requests.map((r) => r.url)]))].filter((u) => u.startsWith(DEV_ORIGIN)));
    // The observer's one-time link (on the observer's own origin) is excluded: it carries the session token by design.
    const errors = pages.flatMap((p) => consoleErrors(p));
    assert.deepEqual(offenders, []);
    assert.deepEqual(prose, []);
    assert.deepEqual([...new Set(errors)], []);
  });
});
